/** Block Chrome/Edge default menu on the chart app; keep native menu on text fields only. */
function v9BlockBrowserContextMenu(e) {
  const t = e.target;
  if (!t || typeof t.closest !== "function") return;
  if (t.closest('input, textarea, select, option, [contenteditable="true"], [contenteditable=""]')) return;
  e.preventDefault();
}

function v9DocumentContextMenuShouldBlock(target) {
  if (!target || typeof target.closest !== "function") return false;
  if (target.closest('input, textarea, select, option, [contenteditable="true"], [contenteditable=""]')) return false;
  if (document.documentElement.classList.contains("multichart-embed")) return true;
  if (target.closest("[data-v9-app]")) return true;
  if (!document.querySelector("[data-v9-app]") && !document.getElementById("chartCanvas")) return false;
  return !!target.closest(
    "#chart-container, #chartWrapper, .chart-wrapper, #panels-container, #chartCanvas, " +
    ".linked-pane-wrapper, .chart-context-menu, .tv-context-menu, .drawing-style-editor, " +
    ".drawing-toolbar, .chart-settings-modal, .settings-sidebar, #compareModalOverlay, " +
    ".compare-modal-overlay, [data-multichart-grid], [data-v9-chrome], [data-chart-ui]"
  );
}

// ── Color utilities ──────────────────────────────────────────────────────────
function parseColor(str) {
  if (!str) return { r:255, g:255, b:255, a:1 };
  if (str.startsWith('#')) {
    const h = str.length===4 ? '#'+str[1]+str[1]+str[2]+str[2]+str[3]+str[3] : str;
    return { r:parseInt(h.slice(1,3),16), g:parseInt(h.slice(3,5),16), b:parseInt(h.slice(5,7),16), a:1 };
  }
  const m = str.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*,\s*([\d.]+))?\s*\)/);
  if (m) return { r:+m[1], g:+m[2], b:+m[3], a: m[4]!=null ? +m[4] : 1 };
  return { r:255, g:255, b:255, a:1 };
}
function rgbToHsv(r, g, b) {
  r/=255; g/=255; b/=255;
  const max=Math.max(r,g,b), min=Math.min(r,g,b), d=max-min;
  let h=0, s=max===0?0:d/max, v=max;
  if (d) { if(max===r) h=(g-b)/d+(g<b?6:0); else if(max===g) h=(b-r)/d+2; else h=(r-g)/d+4; h/=6; }
  return { h:h*360, s, v };
}
function hsvToRgb(h, s, v) {
  h/=360;
  const i=Math.floor(h*6), f=h*6-i, p=v*(1-s), q=v*(1-f*s), t=v*(1-(1-f)*s);
  let r,g,b;
  switch(i%6){case 0:r=v;g=t;b=p;break;case 1:r=q;g=v;b=p;break;case 2:r=p;g=v;b=t;break;case 3:r=p;g=q;b=v;break;case 4:r=t;g=p;b=v;break;default:r=v;g=p;b=q;}
  return { r:Math.round(r*255), g:Math.round(g*255), b:Math.round(b*255) };
}
const toHex2 = n => Math.max(0,Math.min(255,Math.round(n))).toString(16).padStart(2,'0');
function cpBuildColor(r, g, b, a) {
  return a>=1 ? `#${toHex2(r)}${toHex2(g)}${toHex2(b)}` : `rgba(${r},${g},${b},${+a.toFixed(2)})`;
}

/** Settings color swatch — soft border stays visible when fill is dark or transparent. */
function v9TlColorSwatchBoxStyle(color, opts = {}) {
  const {
    active = false,
    hover = false,
    disabled = false,
    size = 26,
    borderRadius,
    extra = null,
  } = opts;
  const on = (active || hover) && !disabled;
  const raw = color != null ? String(color).trim() : "";
  const isEmpty =
    !raw || raw === "none" || raw === "transparent" || raw === "rgba(0,0,0,0)";
  const fill = isEmpty ? "rgba(255,255,255,0.06)" : raw;
  return {
    width: size,
    height: size,
    background: fill,
    cursor: disabled ? "not-allowed" : "default",
    flexShrink: 0,
    boxSizing: "border-box",
    opacity: disabled ? 0.35 : 1,
    border: `1px solid ${on ? "rgba(140, 160, 255, 0.72)" : "rgba(140, 160, 255, 0.42)"}`,
    outline: active ? "2px solid rgba(140,160,255,0.55)" : "none",
    outlineOffset: 1,
    boxShadow: on
      ? "inset 0 0 0 1px rgba(255,255,255,0.24), 0 0 6px rgba(74,106,255,0.35)"
      : "inset 0 0 0 1px rgba(255,255,255,0.2), 0 0 0 1px rgba(0,0,0,0.45)",
    transition: "border-color 0.12s, box-shadow 0.12s",
    ...(borderRadius != null ? { borderRadius } : {}),
    ...(extra && typeof extra === "object" ? extra : {}),
  };
}

