  const [omEntryRowStatLines, setOmEntryRowStatLines] = useState([]);
  const [omTpRowStatLines, setOmTpRowStatLines] = useState([]);
  const [omMultiEntryTotalQtyTxt, setOmMultiEntryTotalQtyTxt] = useState("");
