    const all = ["1m", "5m", "15m", "30m", "1h", "4h", "1D", "1W"];
    const curMin = timeframeToMinutes(tf);
    if (!curMin) return ["Auto", ...all];
    const smaller = all.filter((x) => {
      const v = timeframeToMinutes(x);
      return Number.isFinite(v) && v < curMin;
    });
