                const defaultTimeLevels = [{on:true,value:"0",color:"#787B86"},{on:true,value:"0.25",color:"#F44336"},{on:true,value:"0.5",color:"#FF9800"},{on:true,value:"0.75",color:"#FFEB3B"},{on:true,value:"1",color:"#4CAF50"}];
