                  {isH&&<div style={{position:"absolute",left:0,top:"15%",bottom:"15%",width:2,background:`linear-gradient(180deg,transparent,${item.col},transparent)`,boxShadow:`0 0 6px ${item.col}44`}}/>}
                  <I n={item.icon} s={15} cl={iconCol}/>
